    const DROPDOWN_LISTS = {"Customer Type": ["Business", "Individual"], "Legal Registration Type": ["TL (Commercial/Trade License)", "EID (Emirates ID)", "PAS (Passport)", "CD (Cabinet Decision)"], "UAE Emirate Code": ["AUH", "DXB", "SHJ", "AJM", "UAQ", "RAK", "FUJ"], "Country Code (ISO 3166-1)": ["AE - United Arab Emirates", "SA - Saudi Arabia", "OM - Oman", "QA - Qatar", "KW - Kuwait", "BH - Bahrain", "IN - India", "PK - Pakistan", "GB - United Kingdom", "US - United States", "CN - China", "DE - Germany", "FR - France", "JP - Japan", "SG - Singapore", "CH - Switzerland", "NL - Netherlands", "IT - Italy", "AU - Australia", "CA - Canada", "EG - Egypt", "JO - Jordan", "TR - Turkey", "Other (Use 2-Letter Code)"], "Invoice Type Code": ["380 (Tax Invoice)", "381 (Tax Credit Note)", "480 (Commercial Invoice - Out of Scope)", "81 (Commercial Credit Note)", "389 (Self-Billed Tax Invoice)", "261 (Self-Billed Tax Credit Note)"], "Currency Code (ISO 4217)": ["AED", "USD", "EUR", "GBP", "SAR", "OMR", "KWD", "BHD", "QAR", "INR", "PKR", "CNY", "JPY", "CAD", "AUD", "CHF", "SGD", "MYR", "THB", "HKD", "NZD", "ZAR", "TRY", "EGP", "JOD", "LBP", "PHP", "BRL", "RUB", "KRW"], "Transaction Scenario Flags": ["00000000 (Standard Domestic)", "10000000 (Free Trade Zone)", "01000000 (Deemed Supply)", "00100000 (Margin Scheme)", "00010000 (Summary Invoice)", "00001000 (Continuous Supply)", "00000100 (Disclosed Agent Billing)", "00000010 (E-Commerce Supply)", "00000001 (Export)"], "Payment Means Code": ["1 (Not Defined)", "10 (Cash)", "20 (Cheque)", "21 (Banker's Draft)", "30 (Credit Transfer / Bank Transfer)", "49 (Direct Debit)", "54 (Credit Card)", "55 (Debit Card)", "68 (Online Payment)"], "Tax Category Code": ["S (Standard Rate 5%)", "Z (Zero-Rated 0%)", "E (Exempt from VAT)", "O (Out of Scope / No VAT)", "AE (UAE Reverse Charge)", "N (Margin Scheme / Additional VAT)"], "Tax Rate (%)": ["5.00%", "0.00%", "Leave Blank (Exempt / Out of Scope)"], "Tax Accounting Currency": ["AED", "Leave Blank (Already in AED)"], "Credit Note Reason Code": ["DL8.61.1.A (Supply Cancelled)", "DL8.61.1.B (Tax Treatment Changed)", "DL8.61.1.C (Price Changed)", "DL8.61.1.D (Goods or Services Returned)", "DL8.61.1.E (Tax Charged by Mistake)", "VD (Volume Discount)"], "Incoterms Code": ["EXW", "FCA", "FAS", "FOB", "CFR", "CIF", "CPT", "CIP", "DAP", "DPU", "DDP"], "Item Type (G/S/B)": ["G (Goods)", "S (Services)", "B (Both Goods & Services)"], "Billing Frequency": ["DLY (Daily)", "WKY (Weekly)", "Q15 (Every 15 Days)", "MTH (Monthly)", "Q45 (Every 45 Days)", "Q60 (Every 60 Days)", "QTR (Quarterly)", "HYR (Half-Yearly)", "YRL (Yearly)", "OTH (Other - Write in Note)"], "Peppol Endpoint Fallback": ["0235:<10-digit TIN> (UAE Peppol Registered)", "0235:9900000098 (Not Yet Onboarded / Out of Scope)", "0235:9900000099 (Export - Foreign Buyer)", "0235:9900000097 (Deemed Supply)"], "RCM Goods/Services Type": ["Electronic Devices", "Precious Metals & Precious Stones", "Crude or Refined Oil", "Unprocessed or Processed Natural Gas", "Pure Hydrocarbons", "Metal Scrap Trading"], "UoM_RANGE": ["H87 (piece)", "EA (each)", "C62 (one unit)", "KGM (kilogram)", "GRM (gram)", "TNE (metric ton)", "HUR (hour)", "DAY (day)", "MON (month)", "MTR (metre)", "LTR (litre)", "SET (set)", "E48 (service unit)", "XBX (Box)", "XPK (Package)", "XCT (Carton)", "XUN (Unit)"]};
    const API_DOCS_URL = "https://docs.ae.Ardentaxit.tax/docs";
    const API_DOCS_PASS = "@rdentaxIT2026";
    const STORAGE_KEY = "Ardentax_uae_checklist_readiness_v1";
    const FORM_STORAGE_KEY = "Ardentax_uae_onboarding_form_v1";

    const state = {
      appMode: "form", // "guide" | "form"
      activeModule: "all",
      activeStatus: "all",
      searchQuery: "",
      viewMode: "cards",
      selectedFieldId: null,
      apiUnlocked: false,
      readiness: {},
      // Onboarding Form State
      formRole: null, // "customers" | "suppliers"
      formStep: "pick", // "pick" | "edit" | "saved"
      formValues: {},
      formSavedAt: null,
    };

    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) state.readiness = JSON.parse(saved) || {};
      const savedForm = localStorage.getItem(FORM_STORAGE_KEY);
      if (savedForm) {
        const parsed = JSON.parse(savedForm);
        if (parsed && parsed.formValues) state.formValues = parsed.formValues;
      }
    } catch (e) {
      // Ignore storage restrictions
    }

    function saveReadiness() {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state.readiness));
      } catch (e) {}
    }

    function persistFormValues() {
      try {
        localStorage.setItem(FORM_STORAGE_KEY, JSON.stringify({
          formRole: state.formRole,
          formValues: state.formValues,
          formSavedAt: state.formSavedAt,
        }));
      } catch (e) {}
    }

    function escapeHtml(str) {
      return String(str || "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    let toastTimer = null;
    function showToast(msg) {
      const el = document.getElementById("toast");
      el.textContent = msg;
      el.classList.remove("hidden");
      if (toastTimer) clearTimeout(toastTimer);
      toastTimer = setTimeout(() => el.classList.add("hidden"), 2500);
    }

    function statusBadgeClasses(status) {
      if (status === "Mandatory") return "bg-emerald-50 text-emerald-800 border border-emerald-200";
      if (status === "Conditional") return "bg-amber-50 text-amber-800 border border-amber-200";
      return "bg-slate-100 text-slate-700 border border-slate-200";
    }

    function setAppMode(mode) {
      state.appMode = mode;
      const guidePage = document.getElementById("guidePage");
      const formPage = document.getElementById("formPage");
      const btnGuide = document.getElementById("btnModeGuide");
      const btnForm = document.getElementById("btnModeForm");

      if (mode === "guide") {
        guidePage.classList.remove("hidden");
        formPage.classList.add("hidden");
        btnGuide.className = "px-3 py-1.5 rounded-md text-xs font-semibold bg-white text-[#1B365D] shadow-sm transition";
        btnForm.className = "px-3 py-1.5 rounded-md text-xs font-semibold text-slate-600 hover:text-slate-900 transition";
        render();
      } else {
        guidePage.classList.add("hidden");
        formPage.classList.remove("hidden");
        btnForm.className = "px-3 py-1.5 rounded-md text-xs font-semibold bg-white text-[#1B365D] shadow-sm transition";
        btnGuide.className = "px-3 py-1.5 rounded-md text-xs font-semibold text-slate-600 hover:text-slate-900 transition";
        renderFormPage();
      }
      window.scrollTo({ top: 0, behavior: "smooth" });
    }

    // ══════════════════════════════════════════════════════════════════
    // GUIDE PAGE LOGIC
    // ══════════════════════════════════════════════════════════════════
    function getFilteredFields() {
      const q = state.searchQuery.trim().toLowerCase();
      return FIELDS_DATA.filter((f) => {
        if (state.activeModule !== "all" && f.module !== state.activeModule) return false;
        if (state.activeStatus !== "all" && f.status !== state.activeStatus) return false;
        if (q) {
          const hay = [
            f.name, f.moduleLabel, f.status, f.condition, f.meaning,
            f.example, f.pintCode, f.pintRuleId || "", f.mandLabel || "", f.guideLabel || ""
          ].join(" ").toLowerCase();
          if (!hay.includes(q)) return false;
        }
        return true;
      });
    }

    function updateKPIs() {
      const modPool = state.activeModule === "all"
        ? FIELDS_DATA
        : FIELDS_DATA.filter((f) => f.module === state.activeModule);

      const total = modPool.length;
      const mand = modPool.filter((f) => f.status === "Mandatory").length;
      const cond = modPool.filter((f) => f.status === "Conditional").length;
      const opt = modPool.filter((f) => f.status === "Optional").length;
      const ready = modPool.filter((f) => state.readiness[f.id] === "Ready").length;
      const pct = total > 0 ? Math.round((ready / total) * 100) : 0;

      document.getElementById("countTotal").textContent = String(total);
      document.getElementById("countMandatory").textContent = String(mand);
      document.getElementById("countConditional").textContent = String(cond);
      document.getElementById("countOptional").textContent = String(opt);
      document.getElementById("countReady").textContent = ready + " / " + total;
      document.getElementById("readyPercent").textContent = pct + "%";
      document.getElementById("readyBar").style.width = pct + "%";
    }

    function updateFilterButtons() {
      document.querySelectorAll(".module-tab").forEach((btn) => {
        const active = btn.dataset.module === state.activeModule;
        btn.className = "module-tab px-3.5 py-1.5 rounded-lg text-xs sm:text-sm font-medium transition " + (
          active ? "bg-[#1B365D] text-white" : "bg-slate-100 text-slate-700 hover:bg-slate-200"
        );
      });

      document.querySelectorAll(".status-pill").forEach((btn) => {
        const st = btn.dataset.status;
        const active = st === state.activeStatus;
        if (st === "all") {
          btn.className = "status-pill px-3 py-1.5 rounded-lg text-xs font-medium transition " + (
            active ? "bg-slate-800 text-white" : "bg-slate-100 text-slate-700 hover:bg-slate-200"
          );
        } else if (st === "Mandatory") {
          btn.className = "status-pill px-3 py-1.5 rounded-lg text-xs font-medium transition border " + (
            active ? "bg-emerald-700 text-white border-emerald-700" : "bg-emerald-50 text-emerald-800 border-emerald-200 hover:bg-emerald-100"
          );
        } else if (st === "Conditional") {
          btn.className = "status-pill px-3 py-1.5 rounded-lg text-xs font-medium transition border " + (
            active ? "bg-amber-600 text-white border-amber-600" : "bg-amber-50 text-amber-800 border-amber-200 hover:bg-amber-100"
          );
        } else {
          btn.className = "status-pill px-3 py-1.5 rounded-lg text-xs font-medium transition border " + (
            active ? "bg-slate-700 text-white border-slate-700" : "bg-slate-100 text-slate-700 border-slate-200 hover:bg-slate-200"
          );
        }
      });

      const cardsBtn = document.getElementById("btnViewCards");
      const tableBtn = document.getElementById("btnViewTable");
      if (state.viewMode === "cards") {
        cardsBtn.className = "px-3 py-1 rounded-md text-xs font-medium bg-white text-[#1B365D] shadow-sm transition";
        tableBtn.className = "px-3 py-1 rounded-md text-xs font-medium text-slate-600 hover:text-slate-900 transition";
      } else {
        tableBtn.className = "px-3 py-1 rounded-md text-xs font-medium bg-white text-[#1B365D] shadow-sm transition";
        cardsBtn.className = "px-3 py-1 rounded-md text-xs font-medium text-slate-600 hover:text-slate-900 transition";
      }
    }

    function renderQuickLinks(f) {
      const chips = [];
      if (f.pintRuleUrl) {
        chips.push('<a href="' + escapeHtml(f.pintRuleUrl) + '" target="_blank" rel="noopener noreferrer" class="link-stop inline-flex items-center px-2 py-0.5 rounded bg-blue-50 text-blue-700 hover:bg-blue-100 border border-blue-200 text-[11px] font-medium">' + escapeHtml(f.pintRuleId) + '</a>');
      }
      if (f.mandUrl) {
        chips.push('<a href="' + escapeHtml(f.mandUrl) + '" target="_blank" rel="noopener noreferrer" class="link-stop inline-flex items-center px-2 py-0.5 rounded bg-emerald-50 text-emerald-800 hover:bg-emerald-100 border border-emerald-200 text-[11px] font-medium">' + escapeHtml(f.mandLabel) + '</a>');
      }
      if (f.guideUrl) {
        chips.push('<a href="' + escapeHtml(f.guideUrl) + '" target="_blank" rel="noopener noreferrer" class="link-stop inline-flex items-center px-2 py-0.5 rounded bg-teal-50 text-teal-800 hover:bg-teal-100 border border-teal-200 text-[11px] font-medium">' + escapeHtml(f.guideLabel) + '</a>');
      }
      if (f.ddUrl) {
        chips.push('<a href="' + escapeHtml(f.ddUrl) + '" target="_blank" rel="noopener noreferrer" class="link-stop inline-flex items-center px-2 py-0.5 rounded bg-amber-50 text-amber-800 hover:bg-amber-100 border border-amber-200 text-[11px] font-medium">' + escapeHtml(f.ddLabel) + '</a>');
      }
      return chips.length ? chips.join(" ") : '<span class="text-[11px] text-slate-400 italic">No external rule</span>';
    }

    function render() {
      updateKPIs();
      updateFilterButtons();
      const list = getFilteredFields();
      document.getElementById("resultCount").textContent = "Showing " + list.length + " of " + FIELDS_DATA.length + " fields";

      const cardsEl = document.getElementById("cardsContainer");
      const tableEl = document.getElementById("tableContainer");
      const emptyEl = document.getElementById("emptyState");

      if (list.length === 0) {
        cardsEl.classList.add("hidden");
        tableEl.classList.add("hidden");
        emptyEl.classList.remove("hidden");
        return;
      }
      emptyEl.classList.add("hidden");

      if (state.viewMode === "cards") {
        cardsEl.classList.remove("hidden");
        tableEl.classList.add("hidden");
        cardsEl.innerHTML = list.map((f) => {
          const readyVal = state.readiness[f.id] || "";
          const readyBadge = readyVal === "Ready"
            ? '<span class="text-[11px] font-semibold text-blue-700 bg-blue-50 px-2 py-0.5 rounded">Ready</span>'
            : "";
          return (
            '<article data-open-id="' + escapeHtml(f.id) + '" class="field-card card-hover cursor-pointer bg-white rounded-xl border border-slate-200 p-4 flex flex-col justify-between gap-3">' +
              '<div class="space-y-2">' +
                '<div class="flex items-center justify-between gap-2">' +
                  '<span class="text-[11px] font-medium text-slate-500">#' + f.num + ' &middot; ' + escapeHtml(f.moduleLabel) + '</span>' +
                  '<div class="flex items-center gap-1.5">' +
                    readyBadge +
                    '<span class="text-[11px] font-semibold px-2 py-0.5 rounded ' + statusBadgeClasses(f.status) + '">' + escapeHtml(f.status) + '</span>' +
                  '</div>' +
                '</div>' +
                '<div>' +
                  '<h3 class="text-sm font-bold text-[#1B365D] leading-snug">' + escapeHtml(f.name) + '</h3>' +
                  '<div class="text-[11px] font-mono text-slate-400 mt-0.5">' + escapeHtml(f.pintCode) + '</div>' +
                '</div>' +
                '<p class="text-xs text-slate-600 leading-relaxed">' + escapeHtml(f.meaning) + '</p>' +
                '<div class="bg-blue-50/70 border border-blue-100 rounded-lg px-2.5 py-1.5 text-xs text-blue-950">' +
                  '<span class="font-semibold text-blue-700">Example:</span> ' + escapeHtml(f.example) +
                '</div>' +
              '</div>' +
              '<div class="pt-2 border-t border-slate-100 space-y-2">' +
                '<div class="flex flex-wrap gap-1">' + renderQuickLinks(f) + '</div>' +
                '<div class="flex items-center justify-between pt-0.5">' +
                  '<span class="text-[11px] font-semibold text-[#1B365D]">Click for condition &amp; options &rarr;</span>' +
                '</div>' +
              '</div>' +
            '</article>'
          );
        }).join("");
      } else {
        cardsEl.classList.add("hidden");
        tableEl.classList.remove("hidden");
        const tbody = document.getElementById("tableBody");
        tbody.innerHTML = list.map((f) => {
          const cur = state.readiness[f.id] || "";
          return (
            '<tr data-open-id="' + escapeHtml(f.id) + '" class="field-row hover:bg-slate-50 cursor-pointer transition">' +
              '<td class="py-2.5 px-3 font-semibold text-slate-500">' + f.num + '</td>' +
              '<td class="py-2.5 px-3">' +
                '<div class="font-semibold text-[#1B365D]">' + escapeHtml(f.name) + '</div>' +
                '<div class="text-[11px] text-slate-400">' + escapeHtml(f.moduleLabel) + ' &middot; <span class="font-mono">' + escapeHtml(f.pintCode) + '</span></div>' +
              '</td>' +
              '<td class="py-2.5 px-3">' +
                '<span class="inline-block text-[11px] font-semibold px-2 py-0.5 rounded ' + statusBadgeClasses(f.status) + '">' + escapeHtml(f.status) + '</span>' +
              '</td>' +
              '<td class="py-2.5 px-3 text-slate-700 leading-snug">' + escapeHtml(f.condition) + '</td>' +
              '<td class="py-2.5 px-3"><span class="inline-block bg-blue-50 text-blue-900 px-2 py-0.5 rounded text-[11px] font-medium">' + escapeHtml(f.example) + '</span></td>' +
              '<td class="py-2.5 px-3"><div class="flex flex-wrap gap-1">' + renderQuickLinks(f) + '</div></td>' +
              '<td class="py-2.5 px-3">' +
                '<select data-ready-id="' + escapeHtml(f.id) + '" class="ready-select link-stop w-full rounded-md border border-slate-300 bg-white px-2 py-1 text-xs text-slate-700">' +
                  '<option value=""' + (cur === "" ? " selected" : "") + '>Not Set</option>' +
                  '<option value="Ready"' + (cur === "Ready" ? " selected" : "") + '>Ready</option>' +
                  '<option value="Needs Setup"' + (cur === "Needs Setup" ? " selected" : "") + '>Needs Setup</option>' +
                  '<option value="Missing"' + (cur === "Missing" ? " selected" : "") + '>Missing</option>' +
                  '<option value="Not Needed"' + (cur === "Not Needed" ? " selected" : "") + '>Not Needed</option>' +
                '</select>' +
              '</td>' +
            '</tr>'
          );
        }).join("");
      }
    }

    // ══════════════════════════════════════════════════════════════════
    // FILLABLE CUSTOMER / SUPPLIER FORM LOGIC
    // ══════════════════════════════════════════════════════════════════
    const EXTRA_ADDR3_FIELDS = {
      customers: {
        id: "customers-addr3",
        num: 23,
        module: "customers",
        moduleLabel: "1. Customers (Ardentax)",
        name: "Buyer Address Line 3",
        status: "Optional",
        condition: "Optional third address line (maps to Address Line 3 in Ardentax bulk upload).",
        meaning: "Extra address line such as tower wing, building landmark, or zone.",
        example: "Al Maryah Tower, Wing B",
        dropdownKey: null,
        pintCode: "IBT-163",
      },
      suppliers: {
        id: "suppliers-addr3",
        num: 20,
        module: "suppliers",
        moduleLabel: "2. Suppliers (Ardentax)",
        name: "Seller Address Line 3",
        status: "Optional",
        condition: "Optional third address line (maps to Address Line 3 in Ardentax bulk upload).",
        meaning: "Extra address line such as tower wing, building landmark, or zone.",
        example: "Tower B, Office Wing",
        dropdownKey: null,
        pintCode: "IBT-162",
      },
    };

    function getFormFields() {
      if (!state.formRole) return [];
      const base = FIELDS_DATA.filter((f) => f.module === state.formRole);
      const extra = EXTRA_ADDR3_FIELDS[state.formRole];
      if (!extra) return base;
      const out = [];
      base.forEach((f) => {
        out.push(f);
        if (f.id === "customers-19" || f.id === "suppliers-18") {
          out.push(extra);
        }
      });
      return out;
    }

    function getRoleTitle() {
      return state.formRole === "customers" ? "Customer (Buyer) Onboarding Form" : "Supplier (Seller) Onboarding Form";
    }

    function updateFormProgress() {
      const fields = getFormFields();
      const mand = fields.filter((f) => f.status === "Mandatory");
      const filled = mand.filter((f) => (state.formValues[f.id] || "").trim().length > 0).length;
      const el = document.getElementById("formMandatoryProgress");
      if (el) el.textContent = filled + " of " + mand.length + " Mandatory filled";
    }

    function renderFormPage() {
      const picker = document.getElementById("formRolePicker");
      const editor = document.getElementById("formEditor");
      const savedView = document.getElementById("formSavedView");

      picker.classList.add("hidden");
      editor.classList.add("hidden");
      savedView.classList.add("hidden");

      if (state.formStep === "pick" || !state.formRole) {
        picker.classList.remove("hidden");
        return;
      }

      if (state.formStep === "edit") {
        editor.classList.remove("hidden");
        document.getElementById("formRoleBadge").textContent =
          state.formRole === "customers" ? "Customer (Buyer)" : "Supplier (Seller)";
        document.getElementById("formEditorTitle").textContent = getRoleTitle();
        document.getElementById("formValidationBanner").classList.add("hidden");

        const fields = getFormFields();
        const groups = [
          { key: "Mandatory", title: "Mandatory Fields (Required)", badge: "bg-emerald-600 text-white", border: "border-emerald-200" },
          { key: "Conditional", title: "Conditional Fields (Fill Only If It Applies)", badge: "bg-amber-500 text-white", border: "border-amber-200" },
          { key: "Optional", title: "Optional Fields (Good to Have)", badge: "bg-slate-600 text-white", border: "border-slate-200" },
        ];

        const container = document.getElementById("formFieldsContainer");
        container.innerHTML = groups.map((g) => {
          const gFields = fields.filter((f) => f.status === g.key);
          return (
            '<div class="bg-white rounded-xl border ' + g.border + ' shadow-sm overflow-hidden">' +
              '<div class="px-4 py-2.5 bg-slate-50 border-b border-slate-200 flex items-center justify-between">' +
                '<span class="text-xs font-bold text-[#1B365D]">' + escapeHtml(g.title) + '</span>' +
                '<span class="text-[11px] font-semibold px-2 py-0.5 rounded ' + g.badge + '">' + gFields.length + ' fields</span>' +
              '</div>' +
              '<div class="p-4 grid grid-cols-1 md:grid-cols-2 gap-4">' +
                gFields.map((f) => renderFormFieldInput(f)).join("") +
              '</div>' +
            '</div>'
          );
        }).join("");

        updateFormProgress();
        return;
      }

      // Step 3: Saved View
      savedView.classList.remove("hidden");
      const fields = getFormFields();
      const filledCount = fields.filter((f) => (state.formValues[f.id] || "").trim().length > 0).length;
      document.getElementById("savedFormTitle").textContent = getRoleTitle();
      document.getElementById("savedFormMeta").textContent =
        "Saved on " + (state.formSavedAt || new Date().toLocaleString()) + " · Download Summary Excel, Ardentax Import Excel (Master V1.0), Word, or PDF.";
      document.getElementById("savedFilledCount").textContent = filledCount + " of " + fields.length + " fields filled";

      document.getElementById("savedTableBody").innerHTML = fields.map((f) => {
        const val = (state.formValues[f.id] || "").trim();
        return (
          '<tr class="hover:bg-slate-50">' +
            '<td class="py-2.5 px-3 font-semibold text-slate-500">' + f.num + '</td>' +
            '<td class="py-2.5 px-3 font-semibold text-[#1B365D]">' + escapeHtml(f.name) + '</td>' +
            '<td class="py-2.5 px-3"><span class="inline-block text-[11px] font-semibold px-2 py-0.5 rounded ' + statusBadgeClasses(f.status) + '">' + escapeHtml(f.status) + '</span></td>' +
            '<td class="py-2.5 px-3">' + (val ? '<span class="font-medium text-slate-900">' + escapeHtml(val) + '</span>' : '<span class="italic text-slate-400">Left blank</span>') + '</td>' +
            '<td class="py-2.5 px-3 font-mono text-[11px] text-slate-500">' + escapeHtml(f.pintCode) + '</td>' +
          '</tr>'
        );
      }).join("");
    }

    function renderFormFieldInput(f) {
      const curVal = state.formValues[f.id] || "";
      const isMand = f.status === "Mandatory";
      const opts = (f.dropdownKey && DROPDOWN_LISTS[f.dropdownKey]) ? DROPDOWN_LISTS[f.dropdownKey] : null;
      let inputHtml = "";

      if (opts) {
        const isCustom = curVal && !opts.includes(curVal);
        inputHtml =
          '<div class="space-y-1.5">' +
            '<select data-field-select="' + escapeHtml(f.id) + '" class="form-select-input w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-blue-500">' +
              '<option value="">-- Choose an option --</option>' +
              opts.map((o) => '<option value="' + escapeHtml(o) + '"' + (curVal === o ? " selected" : "") + '>' + escapeHtml(o) + '</option>').join("") +
              '<option value="__CUSTOM__"' + (isCustom ? " selected" : "") + '>Other (Type custom value...)</option>' +
            '</select>' +
            '<input type="text" data-field-custom="' + escapeHtml(f.id) + '" value="' + escapeHtml(isCustom ? curVal : "") + '" placeholder="Type your custom value (e.g., ' + escapeHtml(f.example) + ')" ' +
              'class="form-custom-input ' + (isCustom ? "" : "hidden ") + 'w-full rounded-lg border border-blue-300 bg-blue-50/40 px-3 py-1.5 text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-blue-500" />' +
          '</div>';
      } else {
        inputHtml =
          '<input type="text" data-field-text="' + escapeHtml(f.id) + '" value="' + escapeHtml(curVal) + '" placeholder="e.g., ' + escapeHtml(f.example) + '" ' +
            'class="form-text-input w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500" />';
      }

      return (
        '<div data-field-wrap="' + escapeHtml(f.id) + '" class="space-y-1.5">' +
          '<div class="flex items-start justify-between gap-2">' +
            '<label class="text-xs font-bold text-slate-800">' +
              '#' + f.num + '. ' + escapeHtml(f.name) + (isMand ? ' <span class="text-red-600">*</span>' : '') +
            '</label>' +
            '<span class="text-[10px] font-mono text-slate-400 shrink-0">' + escapeHtml(f.pintCode) + '</span>' +
          '</div>' +
          inputHtml +
          '<p class="text-[11px] text-slate-500 leading-snug">' + escapeHtml(f.condition) + '</p>' +
        '</div>'
      );
    }

    async function saveOnboardingForm() {
      const fields = getFormFields();
      const missing = [];
      fields.forEach((f) => {
        const wrap = document.querySelector('[data-field-wrap="' + f.id + '"]');
        const val = (state.formValues[f.id] || "").trim();
        if (f.status === "Mandatory" && !val) {
          missing.push(f);
          if (wrap) wrap.classList.add("p-2", "rounded-lg", "bg-red-50", "border", "border-red-200");
        } else if (wrap) {
          wrap.classList.remove("p-2", "rounded-lg", "bg-red-50", "border", "border-red-200");
        }
      });

      const banner = document.getElementById("formValidationBanner");
      if (missing.length > 0) {
        banner.textContent = "Please fill all Mandatory fields before saving. Missing (" + missing.length + "): " +
          missing.slice(0, 4).map((m) => m.name).join(", ") + (missing.length > 4 ? " and more..." : ".");
        banner.classList.remove("hidden");
        banner.scrollIntoView({ behavior: "smooth", block: "center" });
        return;
      }

      banner.classList.add("hidden");
      {
        const recordLabel = state.formRole === "customers" ? "customer" : "supplier";
        banner.textContent = "Saving " + recordLabel + " information to Firebase...";
        banner.classList.remove("hidden");
        try {
          if (typeof window.saveCustomerRecord !== "function") {
            throw new Error("Firebase form saving is not available.");
          }
          await window.saveCustomerRecord({
            formRole: getRoleTitle(),
            fields,
            values: state.formValues,
          });
        } catch (error) {
          console.error("Could not save " + recordLabel + " form to Firebase:", error);
          banner.textContent = "Could not save your " + recordLabel + " details to Firebase. " + (error.message || "Check your connection and Firestore permissions, then try again.");
          banner.classList.remove("hidden");
          banner.scrollIntoView({ behavior: "smooth", block: "center" });
          return;
        }
        banner.classList.add("hidden");
      }
      state.formSavedAt = new Date().toLocaleString();
      state.formStep = "saved";
      persistFormValues();
      renderFormPage();
      window.scrollTo({ top: 0, behavior: "smooth" });
      const savedMessage = (state.formRole === "customers" ? "Customer" : "Supplier") + " details saved to Firebase! Choose Excel, Word, or PDF to download.";
      if (state.formRole === "suppliers") {
        window.alert("Supplier form saved successfully to Firebase.");
      }
      showToast(savedMessage);
    }

    // ══════════════════════════════════════════════════════════════════
    // DOWNLOAD EXPORTS: EXCEL (.xlsx), WORD (.doc), PDF (.pdf)
    // ══════════════════════════════════════════════════════════════════
    function triggerBlobDownload(blob, filename) {
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    }

    function downloadFormExcel() {
      const fields = getFormFields();
      const roleSlug = state.formRole === "customers" ? "Customer" : "Supplier";
      const rows = [
        ["Ardentax UAE E-Invoicing — " + getRoleTitle()],
        ["Saved Date:", state.formSavedAt || new Date().toLocaleString()],
        [],
        ["No.", "Field Name", "Requirement", "Entered Value", "PINT-AE Code", "When Needed (Condition)"],
        ...fields.map((f) => [
          f.num, f.name, f.status, (state.formValues[f.id] || "").trim(), f.pintCode, f.condition
        ]),
      ];

      if (window.XLSX && window.XLSX.utils) {
        const wb = window.XLSX.utils.book_new();
        const ws = window.XLSX.utils.aoa_to_sheet(rows);
        ws["!cols"] = [
          { wch: 6 }, { wch: 34 }, { wch: 14 }, { wch: 36 }, { wch: 18 }, { wch: 48 }
        ];
        window.XLSX.utils.book_append_sheet(wb, ws, roleSlug + " Details");
        window.XLSX.writeFile(wb, "Ardentax_" + roleSlug + "_Onboarding_Form.xlsx");
        showToast("Downloaded Excel (.xlsx)");
      } else {
        const csv = rows.map((r) => r.map((v) => '"' + String(v || "").replace(/"/g, '""') + '"').join(",")).join("\\r\\n");
        triggerBlobDownload(new Blob([csv], { type: "text/csv;charset=utf-8;" }), "Ardentax_" + roleSlug + "_Onboarding_Form.csv");
        showToast("Downloaded spreadsheet (.csv fallback)");
      }
    }


