    const COUNTRY_CODE_MAP = {};
    Ardentax_DATA_DICT_COL_A.slice(7, 258).forEach((entry) => {
      const m = entry.match(/\\(([A-Z0-9]{2})\\)\\s*$/);
      if (m) COUNTRY_CODE_MAP[m[1].toUpperCase()] = entry;
    });

    function formatTemplateCountry(raw) {
      const v = String(raw || "").trim();
      if (!v) return "";
      if (Ardentax_DATA_DICT_COL_A.includes(v)) return v;
      // Extract 2-letter ISO code from formats like "AE", "AE - United Arab Emirates", "GB (if PAS selected)"
      const lead = v.match(/^([A-Za-z]{2})(?:\\b|\\s|-)/);
      if (lead && COUNTRY_CODE_MAP[lead[1].toUpperCase()]) {
        return COUNTRY_CODE_MAP[lead[1].toUpperCase()];
      }
      const paren = v.match(/\\(([A-Za-z0-9]{2})\\)/);
      if (paren && COUNTRY_CODE_MAP[paren[1].toUpperCase()]) {
        return COUNTRY_CODE_MAP[paren[1].toUpperCase()];
      }
      // Fallback: match by country name substring
      const low = v.toLowerCase();
      const found = Ardentax_DATA_DICT_COL_A.slice(7, 258).find((c) => c.toLowerCase().includes(low));
      return found || v;
    }

    function formatTemplateRegType(raw) {
      const v = String(raw || "").trim();
      if (!v) return "";
      const u = v.toUpperCase();
      if (u.startsWith("TL") || u.includes("TRADE LICENSE") || u.includes("(TL)")) return "Commercial/Trade License (TL)";
      if (u.startsWith("EID") || u.includes("EMIRATES ID") || u.includes("(EID)")) return "Emirates ID (EID)";
      if (u.startsWith("PAS") || u.includes("PASSPORT") || u.includes("(PAS)")) return "Passport (PAS)";
      if (u.startsWith("CD") || u.includes("CABINET") || u.includes("(CD)")) return "Cabinet Decision (CD)";
      if (u.startsWith("OTH") || u.includes("COMPANY ID") || u.includes("(OTH)")) return "Company ID (OTH)";
      return v;
    }

    function formatTemplateParticipantId(raw) {
      const v = String(raw || "").trim();
      if (!v) return "";
      // Strip helper descriptions like " (UAE Peppol Registered)"
      return v.replace(/\\s*\\([^)]*\\)\\s*$/, "").trim();
    }

    function cleanDigitsOrText(raw) {
      return String(raw || "").trim();
    }

    function downloadArdentaxImportExcel() {
      const isCustomer = state.formRole === "customers";
      const val = (id) => String(state.formValues[id] || "").trim();
      let headers, dataRow, filename;

      if (isCustomer) {
        headers = Ardentax_CUSTOMER_HEADERS;
        const custType = val("customers-1") || "Business";
        const displayName = val("customers-2");
        const tradingName = val("customers-18");
        const businessName = custType === "Business" ? (tradingName || displayName) : "";
        const email = val("customers-3");
        const addr1 = val("customers-5");
        const addr2 = val("customers-19");
        const addr3 = val("customers-addr3");
        const city = val("customers-6");
        const country = formatTemplateCountry(val("customers-8"));
        const subdiv = val("customers-7");
        const postal = val("customers-20");
        const phone = val("customers-21");
        const vatNum = cleanDigitsOrText(val("customers-14"));
        const isUae = country.endsWith("(AE)");
        const tin = (custType === "Business" && isUae) ? cleanDigitsOrText(val("customers-9")) : cleanDigitsOrText(val("customers-9"));
        let regType = formatTemplateRegType(val("customers-10"));
        if (custType === "Individual" && regType && regType !== "Passport (PAS)" && regType !== "Emirates ID (EID)") {
          regType = "";
        }
        const regNum = regType ? val("customers-11") : "";
        const authName = regType === "Commercial/Trade License (TL)" ? val("customers-12") : "";
        const passCountry = regType === "Passport (PAS)" ? formatTemplateCountry(val("customers-13")) : "";
        const participantId = formatTemplateParticipantId(val("customers-4"));

        dataRow = [
          custType, displayName, businessName, email, addr1, addr2, addr3,
          city, country, subdiv, postal, phone, vatNum, tin,
          regType, regNum, authName, passCountry, participantId
        ];
        filename = "default-customer-filled.xlsx";
      } else {
        headers = Ardentax_SUPPLIER_HEADERS;
        const legalName = val("suppliers-1");
        const tradingName = val("suppliers-17");
        const nameCol = tradingName || legalName;
        const businessName = legalName;
        const email = val("suppliers-2");
        const addr1 = val("suppliers-6");
        const addr2 = val("suppliers-18");
        const addr3 = val("suppliers-addr3");
        const city = val("suppliers-7");
        const country = formatTemplateCountry(val("suppliers-9"));
        const subdiv = val("suppliers-8");
        const postal = val("suppliers-19");
        const phone = val("suppliers-11");
        const vatNum = cleanDigitsOrText(val("suppliers-14"));
        const tin = cleanDigitsOrText(val("suppliers-10")) || cleanDigitsOrText(val("suppliers-15"));
        const regType = formatTemplateRegType(val("suppliers-4"));
        const regNum = val("suppliers-5");
        const authName = regType === "Commercial/Trade License (TL)" ? val("suppliers-12") : "";
        const passCountry = regType === "Passport (PAS)" ? formatTemplateCountry(val("suppliers-13")) : "";
        const participantId = formatTemplateParticipantId(val("suppliers-3"));

        dataRow = [
          nameCol, businessName, email, addr1, addr2, addr3,
          city, country, subdiv, postal, phone, vatNum, tin,
          regType, regNum, authName, passCountry, participantId
        ];
        filename = "default-supplier-filled.xlsx";
      }

      if (window.XLSX && window.XLSX.utils) {
        const wb = window.XLSX.utils.book_new();
        const wsMaster = window.XLSX.utils.aoa_to_sheet([headers, dataRow]);
        wsMaster["!cols"] = headers.map((h) => ({ wch: Math.min(Math.max(String(h).length + 4, 18), 42) }));
        window.XLSX.utils.book_append_sheet(wb, wsMaster, "Master V1.0");

        const ddRows = Ardentax_DATA_DICT_COL_A.map((item) => [item]);
        const wsDict = window.XLSX.utils.aoa_to_sheet(ddRows);
        wsDict["!cols"] = [{ wch: 56 }];
        window.XLSX.utils.book_append_sheet(wb, wsDict, "Data Dictionary");

        window.XLSX.writeFile(wb, filename);
        showToast("Downloaded Ardentax Import Excel (" + filename + ")");
      } else {
        const csv = [headers, dataRow].map((r) => r.map((v) => '"' + String(v || "").replace(/"/g, '""') + '"').join(",")).join("\\r\\n");
        triggerBlobDownload(new Blob([csv], { type: "text/csv;charset=utf-8;" }), filename.replace(".xlsx", ".csv"));
        showToast("Downloaded Ardentax Import (.csv fallback)");
      }
    }

    function downloadFormWord() {
      const fields = getFormFields();
      const roleSlug = state.formRole === "customers" ? "Customer" : "Supplier";
      const tableRows = fields.map((f) => {
        const val = (state.formValues[f.id] || "").trim() || "—";
        const bg = f.status === "Mandatory" ? "#ECFDF5" : (f.status === "Conditional" ? "#FFFBEB" : "#F1F5F9");
        return (
          '<tr>' +
            '<td style="border:1px solid #CBD5E1;padding:6px 8px;text-align:center;">' + f.num + '</td>' +
            '<td style="border:1px solid #CBD5E1;padding:6px 8px;font-weight:bold;color:#1B365D;">' + escapeHtml(f.name) + '</td>' +
            '<td style="border:1px solid #CBD5E1;padding:6px 8px;text-align:center;background:' + bg + ';font-weight:bold;">' + escapeHtml(f.status) + '</td>' +
            '<td style="border:1px solid #CBD5E1;padding:6px 8px;">' + escapeHtml(val) + '</td>' +
            '<td style="border:1px solid #CBD5E1;padding:6px 8px;font-family:Consolas,monospace;font-size:9pt;">' + escapeHtml(f.pintCode) + '</td>' +
          '</tr>'
        );
      }).join("");

      const wordHtml =
        '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">' +
        '<head><meta charset="utf-8"><title>' + escapeHtml(getRoleTitle()) + '</title></head>' +
        '<body style="font-family:Calibri,Arial,sans-serif;font-size:10.5pt;color:#1E293B;">' +
          '<div style="background:#1B365D;color:#FFFFFF;padding:14px 18px;margin-bottom:14px;">' +
            '<h1 style="margin:0;font-size:16pt;">Ardentax UAE E-Invoicing — ' + escapeHtml(getRoleTitle()) + '</h1>' +
            '<p style="margin:4px 0 0 0;font-size:9.5pt;color:#E2E8F0;">Saved: ' + escapeHtml(state.formSavedAt || new Date().toLocaleString()) + '</p>' +
          '</div>' +
          '<table style="width:100%;border-collapse:collapse;font-size:9.5pt;">' +
            '<thead><tr style="background:#1B365D;color:#FFFFFF;">' +
              '<th style="border:1px solid #1B365D;padding:7px 8px;width:6%;">No.</th>' +
              '<th style="border:1px solid #1B365D;padding:7px 8px;width:30%;text-align:left;">Field Name</th>' +
              '<th style="border:1px solid #1B365D;padding:7px 8px;width:14%;">Status</th>' +
              '<th style="border:1px solid #1B365D;padding:7px 8px;width:36%;text-align:left;">Entered Value</th>' +
              '<th style="border:1px solid #1B365D;padding:7px 8px;width:14%;">PINT-AE</th>' +
            '</tr></thead>' +
            '<tbody>' + tableRows + '</tbody>' +
          '</table>' +
        '</body></html>';

      const blob = new Blob(["\\ufeff", wordHtml], { type: "application/msword;charset=utf-8" });
      triggerBlobDownload(blob, "Ardentax_" + roleSlug + "_Onboarding_Form.doc");
      showToast("Downloaded Word (.doc)");
    }

    function downloadFormPdf() {
      const fields = getFormFields();
      const roleSlug = state.formRole === "customers" ? "Customer" : "Supplier";
      if (!window.jspdf || !window.jspdf.jsPDF) {
        window.print();
        return;
      }
      const { jsPDF } = window.jspdf;
      const doc = new jsPDF({ orientation: "portrait", unit: "pt", format: "a4" });

      doc.setFillColor(27, 54, 93);
      doc.rect(0, 0, 595, 62, "F");
      doc.setTextColor(255, 255, 255);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(14);
      doc.text("Ardentax UAE E-Invoicing — " + getRoleTitle(), 36, 30);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.text("Saved: " + (state.formSavedAt || new Date().toLocaleString()), 36, 47);

      const body = fields.map((f) => [
        String(f.num),
        f.name,
        f.status,
        (state.formValues[f.id] || "").trim() || "—",
        f.pintCode,
      ]);

      doc.autoTable({
        startY: 76,
        head: [["No.", "Field Name", "Status", "Entered Value", "PINT-AE"]],
        body: body,
        theme: "grid",
        styles: { fontSize: 8.5, cellPadding: 5, textColor: [30, 41, 59] },
        headStyles: { fillColor: [27, 54, 93], textColor: [255, 255, 255], fontStyle: "bold" },
        alternateRowStyles: { fillColor: [248, 250, 252] },
        columnStyles: {
          0: { cellWidth: 28, halign: "center" },
          1: { cellWidth: 150, fontStyle: "bold" },
          2: { cellWidth: 66, halign: "center" },
          3: { cellWidth: 205 },
          4: { cellWidth: 74, halign: "center" },
        },
      });

      doc.save("Ardentax_" + roleSlug + "_Onboarding_Form.pdf");
      showToast("Downloaded PDF (.pdf)");
    }

