    function openDetailModal(fieldId) {
      const f = FIELDS_DATA.find((x) => x.id === fieldId);
      if (!f) return;
      state.selectedFieldId = fieldId;

      document.getElementById("detailModuleBadge").textContent = "#" + f.num + " · " + f.moduleLabel;
      const stBadge = document.getElementById("detailStatusBadge");
      stBadge.textContent = f.status;
      stBadge.className = "text-[11px] font-semibold px-2 py-0.5 rounded " + statusBadgeClasses(f.status);
      document.getElementById("detailPintCode").textContent = f.pintCode;
      document.getElementById("detailTitle").textContent = f.name;
      document.getElementById("detailCondition").textContent = f.condition;
      document.getElementById("detailMeaning").textContent = f.meaning;
      document.getElementById("detailExample").textContent = f.example;

      const ddSec = document.getElementById("detailDropdownSection");
      const ddSel = document.getElementById("detailDropdownSelect");
      if (f.dropdownKey && DROPDOWN_LISTS[f.dropdownKey]) {
        const opts = DROPDOWN_LISTS[f.dropdownKey];
        document.getElementById("detailDropdownCount").textContent = opts.length + " options";
        ddSel.innerHTML = opts.map((o) => '<option value="' + escapeHtml(o) + '">' + escapeHtml(o) + '</option>').join("");
        ddSec.classList.remove("hidden");
      } else {
        ddSec.classList.add("hidden");
      }

      const linkCards = [
        {
          title: "Peppol PINT-AE Rule",
          label: f.pintRuleId ? (f.pintRuleId + " Rule Page") : (f.pintRuleNote || "No dedicated PINT-AE rule"),
          url: f.pintRuleUrl,
          cls: "border-blue-200 bg-blue-50 text-blue-800 hover:bg-blue-100",
        },
        {
          title: "MoF Mandatory Fields PDF (V1.1)",
          label: f.mandLabel || "Not listed in Mandatory table",
          url: f.mandUrl,
          cls: "border-emerald-200 bg-emerald-50 text-emerald-800 hover:bg-emerald-100",
        },
        {
          title: "MoF Guidelines PDF (V2.0)",
          label: f.guideLabel || "No specific Guidelines section",
          url: f.guideUrl,
          cls: "border-teal-200 bg-teal-50 text-teal-800 hover:bg-teal-100",
        },
        {
          title: "MoF Data Dictionary PDF",
          label: f.ddLabel || "Not listed in Data Dictionary",
          url: f.ddUrl,
          cls: "border-amber-200 bg-amber-50 text-amber-800 hover:bg-amber-100",
        },
      ];

      document.getElementById("detailLinksGrid").innerHTML = linkCards.map((item) => {
        if (item.url) {
          return (
            '<a href="' + escapeHtml(item.url) + '" target="_blank" rel="noopener noreferrer" class="block rounded-lg border px-3 py-2 transition ' + item.cls + '">' +
              '<div class="text-[10px] font-semibold uppercase tracking-wide opacity-80">' + escapeHtml(item.title) + '</div>' +
              '<div class="text-xs font-bold mt-0.5 flex items-center justify-between gap-1">' +
                '<span>' + escapeHtml(item.label) + '</span><span>&#8599;</span>' +
              '</div>' +
            '</a>'
          );
        }
        return (
          '<div class="rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-slate-400">' +
            '<div class="text-[10px] font-semibold uppercase tracking-wide">' + escapeHtml(item.title) + '</div>' +
            '<div class="text-xs mt-0.5 italic">' + escapeHtml(item.label) + '</div>' +
          '</div>'
        );
      }).join("");

      document.getElementById("detailReadinessSelect").value = state.readiness[f.id] || "";
      document.getElementById("detailModal").classList.remove("hidden");
    }

    function closeDetailModal() {
      document.getElementById("detailModal").classList.add("hidden");
      state.selectedFieldId = null;
    }

    function openPasswordModal() {
      const modal = document.getElementById("passwordModal");
      const form = document.getElementById("pwForm");
      const unlocked = document.getElementById("pwUnlockedView");
      const err = document.getElementById("pwError");
      const input = document.getElementById("pwInput");

      err.classList.add("hidden");
      input.value = "";
      input.type = "password";
      document.getElementById("btnTogglePw").textContent = "Show";

      if (state.apiUnlocked) {
        form.classList.add("hidden");
        unlocked.classList.remove("hidden");
      } else {
        form.classList.remove("hidden");
        unlocked.classList.add("hidden");
        setTimeout(() => input.focus(), 50);
      }
      modal.classList.remove("hidden");
    }

    function closePasswordModal() {
      document.getElementById("passwordModal").classList.add("hidden");
    }

    function copyTextFallback(text) {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(
          () => showToast("Copied example: " + text),
          () => legacyCopy(text)
        );
      } else {
        legacyCopy(text);
      }
    }

    function legacyCopy(text) {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand("copy");
        showToast("Copied example: " + text);
      } catch (e) {
        showToast("Copy unavailable in this browser");
      }
      document.body.removeChild(ta);
    }

    function exportCsv() {
      const headers = ["Module", "No.", "Field Name", "Status", "When Needed", "Description", "Example", "PINT-AE Code", "Peppol Rule", "Client Status"];
      const rows = getFilteredFields().map((f) => [
        f.moduleLabel, f.num, f.name, f.status, f.condition, f.meaning, f.example,
        f.pintCode, f.pintRuleId || "None", state.readiness[f.id] || "Not Set"
      ]);
      const csv = [headers, ...rows]
        .map((r) => r.map((v) => '"' + String(v).replace(/"/g, '""') + '"').join(","))
        .join("\\r\\n");
      triggerBlobDownload(new Blob([csv], { type: "text/csv;charset=utf-8;" }), "Ardentax_UAE_EInvoicing_Fields_Checklist.csv");
      showToast("CSV exported (" + rows.length + " fields)");
    }

